<script setup>
import { ref, watch } from 'vue'
import { ChevronDown, Download, Filter, RefreshCw, Search, ScanSearch, Settings2, FolderOpen, FolderInput, X } from 'lucide-vue-next'
const props=defineProps({keyword:{type:String,default:''},filters:{type:Array,default:()=>[]},total:{type:Number,default:0},filtered:{type:Number,default:0},selected:{type:Number,default:0},running:Boolean,refreshing:Boolean,deleting:Boolean,exporting:Boolean,loading:Boolean,showColumns:Boolean,allowFilteredDelete:Boolean,quickView:{type:String,default:''},customFolder:Boolean,folderName:{type:String,default:'Tất cả tài khoản'}})
const emit=defineEmits(['update:keyword','apply','clear-filter','reset-filters','clear-selection','check','refresh','export','manage','delete-selected','delete-filtered','quick-view','open-filters','open-folders'])
const searchDraft=ref(props.keyword)
watch(()=>props.keyword,value=>{searchDraft.value=value})
function commitSearch(){emit('update:keyword',searchDraft.value);emit('apply')}
function clearSearch(){searchDraft.value='';commitSearch()}
function resetFilters(){searchDraft.value='';emit('reset-filters')}
const fmt=value=>Number(value||0).toLocaleString('vi-VN')
</script>
<template>
 <div class="account-toolbar">
  <div class="account-toolbar-heading"><div class="account-location"><FolderOpen :size="19"/><strong :translate="customFolder ? 'no' : undefined">{{ folderName }}</strong><span>{{ fmt(filtered) }} tài khoản</span></div><el-button class="mobile-folders-trigger" @click="emit('open-folders')"><FolderOpen :size="16"/>Thư mục</el-button><el-dropdown trigger="click" @command="emit('manage',$event)"><el-button text aria-label="Thiết lập bảng"><Settings2 :size="17"/></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="columns">{{ showColumns?'Ẩn cột bổ sung':'Hiện cột bổ sung' }}</el-dropdown-item><el-dropdown-item command="groups">Quản lý thư mục…</el-dropdown-item><el-dropdown-item command="delete-all" divided class="danger-menu-item">Dọn toàn bộ kho…</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div>
  <div class="account-search-row"><el-input v-model="searchDraft" clearable aria-label="Tìm tài khoản" placeholder="Tìm email hoặc tên miền…" enterkeyhint="search" class="account-search" @clear="clearSearch" @keyup.enter="commitSearch"><template #prefix><button type="button" class="account-search-submit" aria-label="Tìm theo email" @click="commitSearch"><Search :size="16"/></button></template></el-input><el-button :type="filters.length?'primary':undefined" plain @click="emit('open-filters')"><Filter :size="15"/><span>Bộ lọc</span><b v-if="filters.length" class="filter-count">{{ filters.length }}</b></el-button></div>
  <div class="account-quick-views" aria-label="Lọc nhanh"><button v-for="item in [{id:'all',label:'Tất cả'},{id:'needs',label:'Cần làm mới AT'},{id:'errors',label:'Cần xử lý'},{id:'paid',label:'Gói trả phí'},{id:'offers',label:'Ưu đãi Plus'}]" :key="item.id" type="button" :aria-pressed="quickView===item.id" :class="{active:quickView===item.id}" @click="emit('quick-view',item.id)">{{ item.label }}</button></div>
  <div v-if="filters.length" class="account-filter-chips" aria-label="Điều kiện đang lọc"><el-tag v-for="item in filters" :key="item.key" closable effect="light" @close="emit('clear-filter',item.key)">{{ item.label }}</el-tag><el-button text size="small" @click="resetFilters">Xóa bộ lọc</el-button></div>
  <div class="account-action-row" :class="{selecting:selected}"><div class="account-selection-summary"><strong>{{ selected?`${fmt(selected)} đã chọn`:`${fmt(filtered)} kết quả` }}</strong><span v-if="!selected && filtered!==total">/ {{ fmt(total) }} trong kho</span><el-button v-if="selected" text size="small" aria-label="Bỏ chọn tài khoản" @click="emit('clear-selection')"><X :size="14"/>Bỏ chọn</el-button></div><div class="account-unified-actions" :class="{'has-context':selected || (allowFilteredDelete && filters.length)}">
   <el-button v-if="selected" class="move-selected" @click="emit('manage','assign')"><FolderInput :size="15"/>Chuyển thư mục</el-button>
   <el-dropdown trigger="click" :disabled="running" @command="emit('check',$event)"><el-button :disabled="running"><ScanSearch :size="15"/><span>Kiểm tra</span><ChevronDown :size="12"/></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="at">Kiểm tra AT</el-dropdown-item><el-dropdown-item command="plan">Kiểm tra gói</el-dropdown-item><el-dropdown-item command="quota">Kiểm tra quota</el-dropdown-item><li class="account-menu-caption" role="presentation">Nâng cao</li><el-dropdown-item command="checkout">Dò checkout…</el-dropdown-item><el-dropdown-item command="offers">Theo dõi ưu đãi…</el-dropdown-item></el-dropdown-menu></template></el-dropdown>
   <el-button type="primary" :loading="refreshing" :disabled="running" @click="emit('refresh')"><RefreshCw v-if="!refreshing" :size="15"/><span>Làm mới AT</span></el-button>
   <el-dropdown trigger="click" @command="emit('export',$event)"><el-button :loading="exporting"><Download v-if="!exporting" :size="15"/><span>Xuất</span><ChevronDown :size="12"/></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="at">Chỉ Access Token (AT)</el-dropdown-item><el-dropdown-item command="email_pw_2fa">Email · Mật khẩu · 2FA</el-dropdown-item><el-dropdown-item command="custom" divided>Định dạng và phạm vi…</el-dropdown-item></el-dropdown-menu></template></el-dropdown>
   <el-dropdown v-if="selected || (allowFilteredDelete && filters.length)" trigger="click"><el-button text aria-label="Thao tác thêm với phạm vi">•••</el-button><template #dropdown><el-dropdown-menu><template v-if="selected"><el-dropdown-item @click="emit('manage','security:change_2fa')">Đổi 2FA…</el-dropdown-item><el-dropdown-item @click="emit('manage','security:change_password')">Đổi mật khẩu…</el-dropdown-item><el-dropdown-item @click="emit('manage','security:logout_all')">Kick tất cả phiên…</el-dropdown-item></template><el-dropdown-item v-if="!selected" @click="emit('manage','assign')">Chuyển kết quả lọc…</el-dropdown-item><el-dropdown-item v-if="selected" :disabled="deleting" class="danger-menu-item" @click="emit('delete-selected')">Xóa {{ fmt(selected) }} tài khoản đã chọn…</el-dropdown-item><el-dropdown-item v-else :disabled="deleting || loading || !filtered" class="danger-menu-item" @click="emit('delete-filtered')">Xóa {{ fmt(filtered) }} kết quả lọc…</el-dropdown-item></el-dropdown-menu></template></el-dropdown>
  </div></div><slot name="extra"/>
 </div>
</template>
<style scoped>
.account-toolbar{padding:20px 20px 0}.account-toolbar-heading{display:flex;align-items:center;gap:9px;margin-bottom:17px}.account-toolbar-heading>.el-dropdown{margin-left:auto}.account-location{display:flex;align-items:center;gap:9px;min-width:0;flex:1}.account-location>svg{color:var(--folder-accent);flex-shrink:0}.account-location strong{font-size:15px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.account-location>span{font-size:10px;color:var(--app-text-dim);white-space:nowrap}.account-toolbar-heading :deep(.el-button){width:30px;padding:0;min-height:30px}.account-search-row{display:flex;gap:9px}.account-search{flex:1;min-width:0}.account-search-submit{display:grid;place-items:center;border:0;background:none;color:var(--app-text-dim);padding:0;cursor:pointer}.account-search-row :deep(.el-button>span){display:flex;gap:6px;align-items:center}.filter-count{background:var(--brand-bg);border-radius:4px;font-size:10px;padding:2px 4px}.account-quick-views{display:flex;gap:4px;margin-top:15px;overflow:auto;padding-bottom:3px}.account-quick-views button{border:0;background:none;color:var(--app-text-muted);padding:8px 10px;border-radius:7px;font:inherit;font-size:11px;white-space:nowrap;cursor:pointer}.account-quick-views button.active{background:var(--brand-bg);color:var(--brand);font-weight:600}.account-quick-views button:hover{background:var(--app-card-hover)}.account-filter-chips{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-top:11px}.account-filter-chips :deep(.el-tag){height:auto;white-space:normal;line-height:1.5;padding-block:3px;max-width:100%}.account-action-row{display:flex;gap:10px;flex-wrap:wrap;align-items:center;justify-content:space-between;padding:13px 0;margin-top:13px;border-top:1px solid var(--app-border)}.account-action-row.selecting{background:var(--brand-bg);margin-inline:-10px;padding-inline:10px;border-radius:9px}.account-selection-summary{display:flex;align-items:center;gap:8px;color:var(--app-text-muted);font-size:10px}.account-selection-summary strong{color:var(--app-title);font-size:11px;font-weight:550}.account-unified-actions{display:flex;gap:6px;flex-wrap:wrap;align-items:center}.account-unified-actions :deep(.el-button){margin:0;font-size:11px!important;min-height:32px;padding:7px 10px}.account-unified-actions :deep(.el-button>span){display:flex;align-items:center;gap:6px}.mobile-folders-trigger{display:none!important}.account-menu-caption{list-style:none;padding:11px 16px 5px;border-top:1px solid var(--app-border);margin-top:5px;color:var(--app-text-muted);font-size:10px}
@media(max-width:1320px){.account-toolbar-heading .mobile-folders-trigger{display:inline-flex!important;width:auto;padding:5px 9px;gap:5px}.account-location>span{display:none}}
@media(max-width:680px){.account-toolbar{padding:16px 14px 0}.account-location strong{font-size:13px}.account-location>svg{display:none}.account-toolbar-heading{gap:4px;margin-bottom:13px}.account-toolbar-heading>.el-dropdown{margin-left:0}.account-quick-views{margin-top:12px;gap:2px}.account-quick-views button{font-size:10px;padding:8px}.account-unified-actions{width:100%;display:grid;grid-template-columns:1fr 1.15fr 1fr;gap:6px}.account-unified-actions>.el-dropdown,.account-unified-actions>.el-dropdown :deep(.el-button){width:100%}.account-unified-actions :deep(.el-button){min-height:38px;font-size:10px!important;padding-inline:6px;justify-content:center}.account-unified-actions .move-selected{grid-column:1/-1}.account-action-row.selecting .account-unified-actions{grid-template-columns:1fr 1fr}.account-selection-summary{min-height:23px}.account-action-row{padding-top:10px;margin-top:10px}.account-filter-chips :deep(.el-tag){font-size:10px}}
</style>
<style scoped>
.mobile-folders-trigger :deep(>span){display:flex;align-items:center;gap:5px}
@media(max-width:680px){.account-unified-actions.has-context{grid-template-columns:1fr 1.15fr .9fr 28px!important}.account-unified-actions.has-context :deep(.el-button>span){gap:4px}.account-unified-actions.has-context>.el-dropdown:last-child :deep(.el-button){padding:0}}
</style>
